-- Doha (lib/city/doha): Qatar's capital, the third city. Its places' ids start "dq-".
--   - The city a place is in: "dq-" is Doha (public.city_of_place, as src/lib/city/cities.ts), so hotels, homes and
--     flights there follow the same rule as Abu Dhabi's: you do them where they are (20270125000000_city_presence).
--   - Flights to and from Doha (src/data/flights/flights.json, checked by scripts/check-life-config.mjs).
--   - Doha's homes: its towers (The Pearl, Lusail, West Bay, Msheireb), villas (Fox Hills, Al Waab) and townhouses
--     (Qanat Quartier, Fox Hills, Al Waab), as rows in the flats table like Dubai's and Abu Dhabi's.

create or replace function public.city_of_place(p_id text) returns text
language sql immutable as $$
  select case when p_id like 'ad-%' then 'abu-dhabi' when p_id like 'dq-%' then 'doha' else 'dubai' end
$$;

create or replace function public.flight_fare(p_from text, p_to text, p_class text) returns bigint
language sql immutable as $$
  select case
    when (p_from, p_to) in (('dubai', 'abu-dhabi'), ('abu-dhabi', 'dubai')) then
      case p_class when 'economy' then 450 when 'business' then 1800 when 'first' then 4500 end
    when (p_from, p_to) in (('dubai', 'doha'), ('doha', 'dubai')) then
      case p_class when 'economy' then 650 when 'business' then 2600 when 'first' then 6500 end
    when (p_from, p_to) in (('abu-dhabi', 'doha'), ('doha', 'abu-dhabi')) then
      case p_class when 'economy' then 600 when 'business' then 2400 when 'first' then 6000 end
  end::bigint
$$;

on conflict (id) do nothing;
